function graphFilePaletteItems() {
    const items = [
        {kind: "command", label: "Save in this browser", keys: "save graph store local", hint: "Ctrl+S",
            run: () => saveCurrentGraph()},
        {kind: "command", label: "Save as…", keys: "save name as copy new", hint: "File",
            run: () => promptSaveGraph()},
        {kind: "command", label: "Download graph file", keys: "export download json file save as", hint: "Ctrl+Shift+S",
            run: () => saveGraphFile()},
        {kind: "command", label: "Import a graph file…", keys: "import open load json file upload", hint: "File",
            run: () => $("#openFileInput")?.click()},
        {kind: "command", label: "Export every graph saved here", keys: "export backup all saves download", hint: "File",
            run: () => exportAllSavedGraphs()}
    ];
    const saves = savedGraphEntries();
    if (saves.length) {
        items.splice(2, 0, ...saves.map(entry => ({
            kind: "command", label: `Load “${entry.name}”`, keys: "load open saved graph browser",
            hint: relativeTime(entry.savedAt), run: () => loadNamedGraph(entry.name)
        })));
    } else {
        items.splice(2, 0, {kind: "command", label: "Nothing saved in this browser yet",
            keys: "load open saved graph browser", hint: "Load",
            run: () => toast("Nothing saved in this browser yet.")});
    }
    return items;
}

// Rename without a double-click: the same in-place title edit, with the name selected, so a
// keyboard-only session can type straight over it. Enter keeps the new name, Escape the old.
function renameSelectedNode() {
    const node = selection.size === 1 ? nodeById([...selection][0]) : null;
    if (!node) { toast("Select one node to rename it.", "error"); return; }
    const el = nodeEl(node.id);
    const titleEl = el ? $("[data-node-title]", el) : null;
    if (!titleEl) { toast(`“${sourceTitle(node)}” is not on screen to rename.`, "error"); return; }
    ensureNodeVisible(node);
    beginTitleEdit(node, titleEl);
}

// A function is named by its definition, and every instance follows it, so this is not the
// same edit as a node's own title: the prompt is the keyboard's own dialog, and an open
// editor's name field is kept in step with the answer.
function renameFunctionDefinition(id) {
    const def = functionById(id);
    if (!def) return;
    const name = prompt("Name this function:", def.name || "");
    if (name === null) return;
    const clean = name.trim().slice(0, 80);
    if (!clean) return;
    def.name = clean;
    if (fnEditor.name && editingFunctionId === id) fnEditor.name.value = clean;
    renderAllNodes();
    saveLocalSoon();
    toast(`Function renamed to “${clean}”`);
}

// The drawer focuses its own search field when it opens, so this is "open the panel and put
// the caret in it" in one call, which is what the row promises.
function openSymbolPalette() {
    if (!symbolDrawerEl) { toast("The symbol panel is not loaded on this page.", "error"); return; }
    setSymbolDrawer(true);
    $("#symSearch", symbolDrawerEl)?.focus();
}

// Shutting it from the box, which hands the keyboard back to the rail button — the same place
// the drawer's own Escape puts it, so the panel leaves no focus behind in a hidden element.
function closeSymbolPalette() {
    if (!symbolDrawerEl) return;
    setSymbolDrawer(false);
    symbolRailBtn?.focus();
}

// The rows inside an open submenu, or null at the top level.
function cmdkSubmenu() {
    const parent = cmdkTrail[cmdkTrail.length - 1];
    if (!parent) return null;
    const sub = typeof parent.sub === "function" ? parent.sub() : parent.sub;
    return Array.isArray(sub) ? sub : [];
}

// Built fresh on each keystroke rather than cached: a function added a moment ago has to be
// findable, and a few hundred small objects cost nothing next to a render.
function commandPaletteItems() {
    // Node-shaped rows take the point the palette hands them; command rows ignore it.
    const items = PALETTE_COMMANDS.map(c => ({kind: "command", label: c.label, keys: c.keys, hint: c.hint, run: c.run}));
    // Auto-run is the one command whose row is written here rather than in the fixed list: it
    // is built under Run graph on every opening, so the label always says what Enter will do
    // to the state the canvas is in now, not the one it started in.
    items.splice(1, 0, {
        kind: "command",
        label: state?.autoRun ? "Turn auto-run off" : "Turn auto-run on",
        keys: "auto run automatic live update rerun toggle",
        hint: state?.autoRun ? "Auto-run on" : "Auto-run off",
        enterHint: state?.autoRun ? "stop re-running as you edit" : "re-run as you edit",
        run: () => toggleAutoRun()
    });
    // The symbol drawer row points at a panel that can already be open, so it is built here
    // too: while the drawer is up the row closes it, and the label says which of the two
    // Enter will do to the panel as it stands.
    const symbolsOpen = Boolean(symbolDrawerEl?.classList.contains("open"));
    items.splice(5, 0, {
        kind: "command",
        label: symbolsOpen ? "Close symbol panel" : "Open symbol panel",
        keys: "symbol symbols cipher ciphers alphabet alphabets glyph glyphs drawer panel browse hide close shut",
        hint: "Symbols",
        enterHint: symbolsOpen ? "close it and put the caret back on its rail" : "open it and put the caret in its search",
        run: () => (symbolsOpen ? closeSymbolPalette() : openSymbolPalette())
    });
    // One node selected, and the box also offers that node's way back. A plain opening puts
    // the inverse right after it; the Ctrl+Shift+K opening swaps the node for it in place, so
    // the row says which of the two it will do.
    const selectedNode = selection.size === 1 ? nodeById([...selection][0]) : null;
    if (selectedNode) {
        const inverse = inverseOpFor(selectedNode);
        items.push({
            kind: "command",
            label: cmdkReplace ? "Replace with inverse" : "Insert inverse",
            keys: `inverse invert undo step back reverse opposite ${inverse || ""}`,
            hint: inverse ? `“${sourceTitle(selectedNode)}” → “${inverse}”` : `no inverse for “${sourceTitle(selectedNode)}”`,
            enterHint: cmdkReplace ? "swap it for its inverse" : "insert the inverse after it",
            run: () => runInverseCommand(selectedNode.id)
        });
    }
    // A node and the operation behind it can share a name (Magic is the one case); the node
    // is the better thing to add, so the operation is not listed a second time.
    const nodeLabels = new Set(GRAPH_ITEMS.map(item => item.label.toLowerCase()));
    for (const item of GRAPH_ITEMS) {
        items.push({kind: "node", label: item.label, keys: `${item.keys} ${item.about}`,
            hint: item.section || "Graph", type: item.type, run: p => addGraphNode(item.type, p?.x, p?.y)});
    }
    // A function can be made from the box too, not just opened: creating one lands in its own
    // canvas with the input and output nodes ready to fill in, the same as the sidebar's button.
    items.push({kind: "command", label: "New function", keys: "function fn subgraph create new blank",
        hint: "Function · new", enterHint: "create a function to edit", run: () => newFunction()});
    for (const fn of state?.functions || []) {
        items.push({kind: "function", label: fn.name, keys: "function subgraph instance",
            hint: "Function", fnId: fn.id, run: p => addFunctionNode(fn.id, p?.x, p?.y)});
    }
    // A function's name belongs to the definition, not to one node's title, so it gets its own
    // row whenever a function is in reach: selected on the canvas, or open in the editor.
    const fnDef = selectedNode?.type === "fn" ? functionById(selectedNode.fnId)
        : editingFunctionId ? functionById(editingFunctionId) : null;
    if (fnDef) {
        items.push({kind: "command", label: `Rename function “${fnDef.name}”`,
            keys: "rename function definition shared name every instance",
            hint: "Function", enterHint: "type a new name for the function",
            run: () => renameFunctionDefinition(fnDef.id)});
    }
    // Symbol ciphers go on the canvas the way the drawer puts them there, so the box offers
    // them too. One row per cipher, named from the index rather than the art: typing
    // "pigpen" finds the cipher before a visit has paid for the download.
    for (const [slug, name] of Object.entries(symbolIndex())) {
        items.push({kind: "symbol", label: name, slug,
            keys: `symbol cipher alphabet glyph transcription ${slug.replace(/[_-]+/g, " ")}`,
            hint: "Symbol cipher", run: p => addSymbolNode(slug, p?.x, p?.y)});
    }
    for (const op of OP_NAMES) {
        if (FLOW_OPS.has(op) || nodeLabels.has(op.toLowerCase())) continue;
        const meta = OPS[op] || {};
        items.push({kind: "op", label: op, keys: `op ${meta.category || ""} ${meta.description || ""}`,
            hint: SILLY_OPS.has(op) ? "Silly Stuff" : (meta.category || "Operation"), op, run: p => addOperationNode(op, p?.x, p?.y)});
    }
    return items;
}

// Ranking, rather than a flat match list: an exact name wins, then a name that starts with
// the query, then a word of the name that does, then anything that merely contains it.
// Every word of the query has to land somewhere, so "xor 13" still finds XOR with key 13.
function rankCommandPalette(query) {
    const items = cmdkSubmenu() || commandPaletteItems();
    const q = query.trim().toLowerCase();
    if (!q) return items.slice(0, 40);
    const words = q.split(/\s+/).filter(Boolean);
    const wordsOf = label => label.split(/[\s/\-–—:()]+/).filter(Boolean);
    const scored = [];
    for (const item of items) {
        const label = item.label.toLowerCase();
        const hay = `${label} ${item.hint} ${item.keys}`.toLowerCase();
        if (!words.every(w => hay.includes(w))) continue;
        let score = label.includes(q) ? 40 : 16;
        if (label === q) score = 100;
        else if (label.startsWith(q)) score = 80;
        else if (wordsOf(label).some(w => w.startsWith(q))) score = 60;
        if (words.every(w => wordsOf(label).some(lw => lw.startsWith(w)))) score += 8;
        if (item.kind === "command") score += 5;
        scored.push({item, score, len: label.length});
    }
    scored.sort((a, b) => b.score - a.score || a.len - b.len || a.item.label.localeCompare(b.item.label));
    return scored.slice(0, 80).map(s => s.item);
}

function highlightCommandPaletteRow(index) {
    if (!cmdkRows.length) return;
    cmdkIndex = (index + cmdkRows.length) % cmdkRows.length;
    for (const row of cmdkList.querySelectorAll("[data-cmdk-row]")) {
        const on = Number(row.dataset.cmdkRow) === cmdkIndex;
        row.classList.toggle("sel", on);
        row.setAttribute("aria-selected", on ? "true" : "false");
        if (on) row.scrollIntoView({block: "nearest"});
    }
    updateCommandPaletteAction();
}

// Placed at the pointer, like a context menu, and clamped so the whole card stays on screen.
// With no pointer known the box is centred on the graph instead — but that choice was made
// when the box opened, not here, so re-running this as the user types never moves it.
function positionCommandPalette() {
    if (!cmdkCard) return;
    const pad = 8;
    const w = cmdkCard.offsetWidth, h = cmdkCard.offsetHeight;
    const at = cmdkPointer && !cmdkCentred ? cmdkPointer : null;
    // The middle of the graph, not the middle of the window: the node list and the toolbar
    // take a column and a strip of the window that are not canvas.
    const rect = stage.getBoundingClientRect();
    let x = at ? at.x : rect.left + (rect.width - w) / 2;
    let y = at ? at.y : rect.top + (rect.height - h) / 2;
    x = Math.min(Math.max(pad, x), Math.max(pad, window.innerWidth - w - pad));
    y = Math.min(Math.max(pad, y), Math.max(pad, window.innerHeight - h - pad));
    cmdkCard.style.left = `${Math.round(x)}px`;
    cmdkCard.style.top = `${Math.round(y)}px`;
}

function renderCommandPalette(query) {
    cmdkRows = rankCommandPalette(query);
    cmdkIndex = 0;
    // The first row of a submenu is the way back to the list that opened it, drawn above the
    // matches and outside them so typing never filters it away.
    const back = cmdkTrail.length
        ? `<div class="cmdk-row cmdk-back" data-cmdk-back="1" title="Back to every command">
            <span class="cmdk-name">‹ ${esc(cmdkTrail[cmdkTrail.length - 1].label)}</span>
            <span class="cmdk-hint">Back</span>
        </div>`
        : "";
    if (!cmdkRows.length) {
        cmdkList.innerHTML = back + `<div class="cmdk-empty">Nothing matched “${esc(query.trim())}”.<br>Try “rot13”, “note” or “save”.</div>`;
        positionCommandPalette();
        return;
    }
    cmdkList.innerHTML = back + cmdkRows.map((item, i) => `<div class="cmdk-row${item.sub ? " has-sub" : ""}" role="option" aria-selected="false" data-cmdk-row="${i}" title="${esc(item.keys || item.label)}">
        <span class="cmdk-name">${esc(item.label)}</span>
        <span class="cmdk-hint">${esc(item.hint || "")}</span>
    </div>`).join("");
    highlightCommandPaletteRow(0);
    positionCommandPalette();
}

function openCommandPalette(replace = false) {
    if (!cmdkEl) return;
    cmdkReplace = Boolean(replace);
    cmdkTrail = [];
    // One placement decision per opening. A pointer that has sat still for a while still
    // counts as the place to open at; only never having had one means centred.
    cmdkCentred = !cmdkPointer;
    cmdkEl.hidden = false;
    cmdkInput.value = "";
    renderCommandPalette("");
    requestAnimationFrame(() => cmdkInput.focus());
}

function closeCommandPalette() {
    if (!cmdkEl || cmdkEl.hidden) return;
    cmdkEl.hidden = true;
    cmdkTrail = [];
    cmdkInput.blur();
}

// One step out: a submenu closes back onto the list that opened it, and the top level closes
// altogether. Escape and Backspace on an empty query both mean this.
function cmdkBack() {
    if (!cmdkTrail.length) { closeCommandPalette(); return; }
    cmdkTrail.pop();
    cmdkInput.value = "";
    renderCommandPalette("");
    cmdkInput.focus();
}

// A row with a `sub` list steps into it instead of closing: the same card, now showing the
// children, with the query cleared so all of them are listed.
function cmdkOpenSubmenu(item) {
    cmdkTrail.push(item);
    cmdkInput.value = "";
    renderCommandPalette("");
    cmdkInput.focus();
}

// What a palette row would build. Commands have no node, which is how "Run graph" and the
// rest keep their own behaviour while every node-shaped row can also be a replacement.
function paletteNodeFor(item) {
    if (!item || item.kind === "command") return null;
    if (item.kind === "op") return OPS[item.op] ? makeNode("op", {op: item.op}) : null;
    // A symbol cipher has no input, so a pick can swap it for another but never splice it
    // into a wire; paletteSpliceEdge leaves it out for the same reason.
    if (item.kind === "symbol") return makeNode("symbol", {symbolCipher: item.slug, symbolSource: "cachesleuth"});
    if (item.kind === "function") return functionById(item.fnId) ? makeNode("fn", {fnId: item.fnId}) : null;
    if (item.kind === "node") return createGraphNode(item.type);
    return null;
}

// Shift is the difference: plain Ctrl+K adds and runs exactly as it always did, and only a
// Ctrl+Shift+K opening swaps. A pick replaces when that opening asked for it and exactly one
// node is selected; everything else takes the add path.
function paletteReplaces(item) {
    if (!cmdkReplace || !item || item.kind === "command" || selection.size !== 1) return false;
    return Boolean(nodeById([...selection][0]));
}

// A selected wire is a target like a selected node: an operation or graph tool picked from the
// box goes into the middle of that wire, which is the same splice a drop on the wire makes.
// Functions are left out because a drop does not splice them either, and a command row is not
// a node. Returns the edge, or null when this pick would not splice.
function paletteSpliceEdge(item) {
    if (!selectedEdge || !item || item.kind === "command") return null;
    if (item.kind !== "op" && !(item.kind === "node" && !["fnin", "fnout"].includes(item.type))) return null;
    return state.edges.find(e => e.id === selectedEdge) || null;
}

// Put a node where another one was, keeping its place on the canvas and every wire the
// replacement still has a port for: the main pipe in and out survives an operation swap, a
// wired argument does not (the arguments it was wired to are gone), and a port the
// replacement does not have takes its wire with it.
function swapNodeInPlace(target, built) {
    if (!target || !built) return false;
    built.x = target.x;
    built.y = target.y;
    const inPorts = new Set(nodeInPorts(built));
    const outPorts = new Set(nodeOutPorts(built));
    const edges = [];
    for (const e of state.edges) {
        if (e.to === target.id) {
            if (!inPorts.has(String(e.toPort))) continue;
            e.to = built.id;
        }
        if (e.from === target.id) {
            if (!outPorts.has(String(e.fromPort || "out"))) continue;
            e.from = built.id;
        }
        edges.push(e);
    }
    state.edges = edges;
    state.nodes = state.nodes.filter(n => n.id !== target.id);
    state.nodes.push(built);
    setSelection([built.id]);
    renderAllNodes();
    onGraphEdited(true);
    toast(`Replaced “${sourceTitle(target)}” with “${sourceTitle(built)}”`);
    return true;
}
// Ctrl+Shift+K with one node selected swaps that node for the pick instead of adding a second
// one. Returns false when there is nothing to replace, so the row can add as usual.
function replaceSelectedNode(item) {
    const target = selection.size === 1 ? nodeById([...selection][0]) : null;
    if (!target || !item || item.kind === "command") return false;
    const built = paletteNodeFor(item);
    // A refusal has already been explained (a function's port declaration outside a function);
    // the canvas is left exactly as it was, which is why this still counts as handled.
    if (!built) return true;
    return swapNodeInPlace(target, built);
}

/* An inverse is the operation that undoes another: “From Base64” undoes “To Base64”, “Leet
 * Decode” undoes “Leet Encode”. The pairs are found in the catalogue itself rather than listed
 * by hand: an operation's name is flipped by turning To into From, or Encode into Decode,
 * Encrypt into Decrypt, Compress into Decompress, Escape into Unescape, Serialize into
 * Deserialize, or by reading “CSV to JSON” back as “JSON to CSV”. If the flipped name is an
 * operation that exists, the two are each other's way back. What is left over is one-way
 * (a hash, a parser) or its own way back, and those self-inverse steps are named below.
 */
const INVERSE_WORDS = [
    ["Encode", "Decode"],
    ["Encrypt", "Decrypt"],
    ["Compress", "Decompress"],
    ["Escape", "Unescape"],
    ["Serialize", "Deserialize"],
    ["Serialise", "Deserialise"]
];
const INVERSE_EXTRAS = [
    // Two directions of one conversion, neither of which says To or From.
    ["To Dvorak", "To Qwerty"],
    // A whole message handed over and read back: the signing is undone by verifying it.
    ["PGP Encrypt and Sign", "PGP Decrypt and Verify"],
    // Steps that undo themselves at the setting they are built around.
    ["Reverse", "Reverse"],
    ["Swap endianness", "Swap endianness"],
    ["ROT13", "ROT13"],
    ["ROT47", "ROT47"]
];
const INVERSE_OPS = (() => {
    const names = new Set(Object.keys(OPS));
    const map = new Map();
    const add = (a, b) => {
        if (!b || a === b || !names.has(a) || !names.has(b)) return;
        if (!map.has(a)) map.set(a, b);
        if (!map.has(b)) map.set(b, a);
    };
    // Whole words only: “Escape” must not match inside “Unescape”.
    const swap = (name, from, to) => name
        .replace(new RegExp(`\\b${from}\\b`, "g"), to)
        .replace(new RegExp(`\\b${from.toLowerCase()}\\b`, "g"), to.toLowerCase());
    for (const op of names) {
        if (op.startsWith("To ")) add(op, "From " + op.slice(3));
        for (const [a, b] of INVERSE_WORDS) {
            add(op, swap(op, a, b));
            add(op, swap(op, b, a));
        }
        const flip = op.match(/^(.+?) to (.+)$/);
        if (flip) add(op, `${flip[2]} to ${flip[1]}`);
    }
    for (const [a, b] of INVERSE_EXTRAS) {
        if (!names.has(a)) continue;
        if (a === b) map.set(a, a);
        else add(a, b);
    }
    return map;
})();

// The inverse of a node, or null when the step cannot be undone by another operation. A
// rotation is its own way back only at the amount it turns by, so a ROT13 node set to 5 gets
// no inverse rather than a wrong one.
function inverseOpFor(node) {
    if (!node || node.type !== "op" || !node.op) return null;
    const inverse = INVERSE_OPS.get(node.op) || null;
    if (!inverse) return null;
    if (inverse !== node.op) return inverse;
    const values = node.values || [];
    if (values[opArgIndex(node.op, "Rotate numbers")]) return null;
    if (node.op === "ROT13" && Number(values[opArgIndex(node.op, "Amount")]) !== 13) return null;
    if (node.op === "ROT47" && Number(values[opArgIndex(node.op, "Amount")]) !== 47) return null;
    return inverse;
}

// Carry the settings both steps understand: a Base64 node set to the URL-safe alphabet hands
// that alphabet to the step that decodes it, and a cipher's key follows its inverse. A setting
// whose default is the opposite on the two steps — an encryptor that reads Raw and writes Hex,
// where the decryptor reads Hex and writes Raw — is left alone, because the inverse's own
// default is the reading that undoes it.
function inverseValuesFor(node, inverse) {
    const values = defaultNodeValues(inverse);
    if (node.op === inverse) return cloneValue(node.values || values);
    const source = OPS[node.op]?.args || [];
    const destination = OPS[inverse]?.args || [];
    const sourceDefaults = OPS[node.op]?.defaults || [];
    const destinationDefaults = OPS[inverse]?.defaults || [];
    destination.forEach((arg, i) => {
        const from = source.findIndex(a => a.name === arg.name);
        if (from < 0 || !node.values || node.values[from] === undefined) return;
        if (JSON.stringify(sourceDefaults[from]) !== JSON.stringify(destinationDefaults[i])) return;
        values[i] = cloneValue(node.values[from]);
    });
    return values;
}

// Inserting puts the undoing step where the chain would continue: right of the node it undoes,
// wired to that node's output.
function insertInverseNode(target, inverse) {
    const node = makeNode("op", {op: inverse, values: inverseValuesFor(target, inverse)});
    const el = nodeEl(target.id);
    node.x = Math.round(target.x + (el ? el.offsetWidth : 330) + 56);
    node.y = Math.round(target.y);
    state.nodes.push(node);
    const fromPort = nodeOutPorts(target)[0] || "out";
    state.edges.push({id: optsEdgeId(), from: target.id, fromPort, to: node.id, toPort: "main"});
    setSelection([node.id]);
    renderAllNodes();
    onGraphEdited(true);
    requestAnimationFrame(() => ensureNodeVisible(node));
    toast(`“${inverse}” inserted — it undoes “${sourceTitle(target)}”`);
    return true;
}
// `replace` is explicit rather than read from the palette, so the keyboard shortcut below is
// never steered by whichever way the box was last opened.
function runInverseCommand(id, replace = cmdkReplace) {
    const target = nodeById(id);
    if (!target) {
        toast("That node is no longer on the canvas.", "error");
        return false;
    }
    const inverse = inverseOpFor(target);
    if (!inverse) {
        toast(`“${sourceTitle(target)}” has no inverse to add.`, "error");
        return false;
    }
    // Ctrl+Shift+K swaps the node for its inverse in place; a plain Ctrl+K inserts after it.
    if (replace) return swapNodeInPlace(target, makeNode("op", {op: inverse, values: inverseValuesFor(target, inverse)}));
    return insertInverseNode(target, inverse);
}

// What Enter will do to the highlighted row. With one node selected, a node-shaped row says
// it will replace that node, so the swap is never a surprise.
function updateCommandPaletteAction() {
    if (!cmdkEnter) return;
    const item = cmdkRows[cmdkIndex];
    // A row that knows what Enter does to the selection says so itself.
    if (item?.enterHint) {
        cmdkEnter.innerHTML = `<kbd>Enter</kbd> ${esc(item.enterHint)}`;
        return;
    }
    const target = paletteReplaces(item) ? nodeById([...selection][0]) : null;
    const wire = target ? null : paletteSpliceEdge(item);
    cmdkEnter.innerHTML = target
        ? `<kbd>Enter</kbd> replace “${esc(sourceTitle(target))}”`
        : wire
            ? `<kbd>Enter</kbd> splice into the wire`
            : `<kbd>Enter</kbd> run`;
}

function runCommandPaletteRow(index) {
    const item = cmdkRows[index];
    if (!item) return;
    if (item.sub) { cmdkOpenSubmenu(item); return; }
    // A node picked from the box goes where the box was: at the pointer, in graph coordinates.
    // Clamped to the canvas, since the shortcut also fires with the pointer over the sidebar.
    let at;
    if (cmdkPointer) {
        const r = stage.getBoundingClientRect();
        const p = screenToWorld(
            Math.min(Math.max(cmdkPointer.x, r.left + 4), r.right - 4),
            Math.min(Math.max(cmdkPointer.y, r.top + 4), r.bottom - 4));
        at = {x: Math.round(p.x), y: Math.round(p.y)};
    }
    closeCommandPalette();
    // With a wire selected, a node-shaped pick goes into that wire at the middle of its curve.
    const spliceEdge = paletteSpliceEdge(item);
    if (spliceEdge) {
        const built = paletteNodeFor(item);
        const middle = built ? wireMidpoint(spliceEdge) : null;
        if (built && middle) {
            if (spliceNodeIntoWire(built, middle, spliceEdge)) return;
            toast(`“${sourceTitle(built)}” has no main input and output, so it cannot go into the wire.`);
        }
    }
    // Only a Ctrl+Shift+K opening replaces; every other opening adds or runs as it always did.
    if (paletteReplaces(item) && replaceSelectedNode(item)) return;
    item.run(at);
}

function initCommandPalette() {
    if (cmdkEl) return;
    cmdkEl = document.createElement("div");
    cmdkEl.id = "cmdk";
    cmdkEl.className = "cmdk";
    cmdkEl.hidden = true;
    cmdkEl.innerHTML = `<div class="cmdk-card" role="dialog" aria-modal="true" aria-label="Command palette">
        <div class="cmdk-head">
            <span class="cmdk-icon"></span>
            <input id="cmdkInput" class="cmdk-input" placeholder="Run a command, or jump to an operation, node, function or symbol cipher…"
                autocomplete="off" spellcheck="false" aria-label="Command palette" aria-controls="cmdkList" aria-autocomplete="list">
            <button class="cmdk-esc" type="button" title="Close">Esc</button>
        </div>
        <div class="cmdk-list" id="cmdkList" role="listbox" aria-label="Matches"></div>
        <div class="cmdk-foot"><span><kbd>↑</kbd><kbd>↓</kbd> choose</span><span id="cmdkEnterHint"><kbd>Enter</kbd> run</span><span><kbd>Ctrl</kbd>+<kbd>Shift</kbd>+<kbd>K</kbd> replaces</span></div>
    </div>`;
    document.body.appendChild(cmdkEl);
    cmdkCard = $(".cmdk-card", cmdkEl);
    cmdkInput = $(".cmdk-input", cmdkEl);
    cmdkList = $(".cmdk-list", cmdkEl);
    cmdkEnter = $(".cmdk-foot #cmdkEnterHint", cmdkEl);
    $(".cmdk-icon", cmdkEl).innerHTML = svg("search");

    // Capture phase so a handler that swallows the event on the canvas cannot hide the
    // pointer from us. Taps count too, for the entry that opens the box without a mouse move.
    const trackPointer = ev => {
        cmdkPointer = {x: ev.clientX, y: ev.clientY};
    };
    window.addEventListener("pointermove", trackPointer, {capture: true, passive: true});
    window.addEventListener("pointerdown", trackPointer, {capture: true, passive: true});
    window.addEventListener("resize", () => { if (!cmdkEl.hidden) positionCommandPalette(); });

    cmdkInput.addEventListener("input", () => renderCommandPalette(cmdkInput.value));
    cmdkInput.addEventListener("keydown", ev => {
        if (ev.key === "ArrowDown") { ev.preventDefault(); highlightCommandPaletteRow(cmdkIndex + 1); }
        else if (ev.key === "ArrowUp") { ev.preventDefault(); highlightCommandPaletteRow(cmdkIndex - 1); }
        else if (ev.key === "Enter") { ev.preventDefault(); runCommandPaletteRow(cmdkIndex); }
        else if (ev.key === "Escape") { ev.preventDefault(); ev.stopPropagation(); cmdkBack(); }
        else if (ev.key === "Backspace" && !cmdkInput.value && cmdkTrail.length) { ev.preventDefault(); cmdkBack(); }
    });
    // A click on the dimmed area closes it; a click on the card is the user's, not the mask's.
    cmdkEl.addEventListener("pointerdown", ev => { if (ev.target === cmdkEl) { ev.preventDefault(); closeCommandPalette(); } });
    $(".cmdk-esc", cmdkEl).addEventListener("click", closeCommandPalette);
    cmdkList.addEventListener("pointermove", ev => {
        const row = ev.target.closest?.("[data-cmdk-row]");
        if (!row) return;
        const i = Number(row.dataset.cmdkRow);
        if (i !== cmdkIndex) highlightCommandPaletteRow(i);
    });
    cmdkList.addEventListener("click", ev => {
        if (ev.target.closest?.("[data-cmdk-back]")) { cmdkBack(); return; }
        const row = ev.target.closest?.("[data-cmdk-row]");
        if (row) runCommandPaletteRow(Number(row.dataset.cmdkRow));
    });
    // Capture phase: the shortcut has to win over the editor's own keys, and over a note or
    // a title that currently has focus, or it would only work from an empty canvas.
    document.addEventListener("keydown", ev => {
        if (!((ev.ctrlKey || ev.metaKey) && !ev.altKey && ev.key.toLowerCase() === "k")) return;
        ev.preventDefault();
        // Shift decides what Enter will do, so it is read at the moment the box opens.
        if (cmdkEl.hidden) openCommandPalette(ev.shiftKey); else closeCommandPalette();
    }, true);
}

function addOperationNode(op, x, y) {
    if (!op || !OPS[op]) return;
    const node = makeNode("op", {op});
    const p = (x === undefined) ? spawnPoint(node) : {x, y};
    node.x = Math.round(p.x);
    node.y = Math.round(p.y);
    state.nodes.push(node);
    setSelection([node.id]);
    renderAllNodes();
    onGraphEdited();
    requestAnimationFrame(() => ensureNodeVisible(node));
    if (window.innerWidth <= 900) closeSidebar();
}

// How close a drop has to be to a wire to count as dropping on it, in world units. The hit
// stroke is 16 wide and centred on the line, so this matches what a click on a wire accepts.
const WIRE_DROP_REACH = 10;

function distanceToSegment(p, a, b) {
    const dx = b.x - a.x;
    const dy = b.y - a.y;
    const len = dx * dx + dy * dy;
    const t = len ? clamp(((p.x - a.x) * dx + (p.y - a.y) * dy) / len, 0, 1) : 0;
    return Math.hypot(p.x - (a.x + t * dx), p.y - (a.y + t * dy));
}

// The cubic a wire is drawn as, so a drop, a click and a pick from the command box all agree
// about where the curve runs.
function wireCurve(a, b) {
    const dx = Math.max(65, Math.abs(b.x - a.x) * 0.42);
    return {a, c1: {x: a.x + dx, y: a.y}, c2: {x: b.x - dx, y: b.y}, b};
}

function wirePoint(curve, t) {
    const u = 1 - t;
    return {
        x: u * u * u * curve.a.x + 3 * u * u * t * curve.c1.x + 3 * u * t * t * curve.c2.x + t * t * t * curve.b.x,
        y: u * u * u * curve.a.y + 3 * u * u * t * curve.c1.y + 3 * u * t * t * curve.c2.y + t * t * t * curve.b.y
    };
}

// Distance from a point to the curve a wire is drawn as, sampled along the same cubic pathFor
// builds so a drop and a click agree about what is under the pointer.
function distanceToWire(p, a, b) {
    const curve = wireCurve(a, b);
    let best = Infinity;
    let prev = a;
    for (let i = 1; i <= 24; i++) {
        const point = wirePoint(curve, i / 24);
        best = Math.min(best, distanceToSegment(p, prev, point));
        prev = point;
    }
    return best;
}

// The wire closest to a world point, or null when the point is not over one.
function wireAtPoint(p) {
    let best = null;
    let bestDistance = Infinity;
    for (const edge of state.edges) {
        const from = nodeById(edge.from);
        const to = nodeById(edge.to);
        if (!from || !to) continue;
        const outEl = nodeEl(from.id)?.querySelector(`.port.out[data-port="${cssEscape(edge.fromPort || "out")}"]`);
        const inEl = nodeEl(to.id)?.querySelector(`.port.in[data-port="${cssEscape(edge.toPort)}"]`);
        const a = portCenter(outEl);
        const b = portCenter(inEl);
        if (!a || !b) continue;
        const distance = distanceToWire(p, a, b);
        if (distance < bestDistance) {
            bestDistance = distance;
            best = edge;
        }
    }
    return bestDistance <= WIRE_DROP_REACH ? best : null;
}

// The middle of the curve a wire is drawn as, in world units: where a pick from the command
// box puts the node it is splicing in.
function wireMidpoint(edge) {
    const from = nodeById(edge.from);
    const to = nodeById(edge.to);
    if (!from || !to) return null;
    const outEl = nodeEl(from.id)?.querySelector(`.port.out[data-port="${cssEscape(edge.fromPort || "out")}"]`);
    const inEl = nodeEl(to.id)?.querySelector(`.port.in[data-port="${cssEscape(edge.toPort)}"]`);
    const a = portCenter(outEl);
    const b = portCenter(inEl);
    return a && b ? wirePoint(wireCurve(a, b), 0.5) : null;
}

// A node dropped onto a wire goes into the middle of it: the wire splits and both halves
// reattach to the node's main ports, so a step can be added to a chain without cutting the
// wire and drawing two new ones. Refused for any node with no main way in and out (a note, a
// flow-control step, a two-sided tool); the caller then drops it beside the wire as usual.
function spliceNodeIntoWire(built, p, edge) {
    if (!built || !edge) return false;
    if (!nodeInPorts(built).includes("main") || !nodeOutPorts(built).includes("out")) return false;
    built.x = Math.round(p.x - 155);
    built.y = Math.round(p.y - 40);
    state.nodes.push(built);
    state.edges = state.edges.filter(e => e.id !== edge.id);
    state.edges.push({id: optsEdgeId(), from: edge.from, fromPort: edge.fromPort || "out", to: built.id, toPort: "main"});
    state.edges.push({id: optsEdgeId(), from: built.id, fromPort: "out", to: edge.to, toPort: edge.toPort});
    setSelection([built.id]);
    renderAllNodes();
    // Now that the card can be measured, sit its middle on the point it was dropped at, so
    // the wire runs into and out of it at the height the pointer was at.
    const el = nodeEl(built.id);
    if (el) {
        built.x = Math.round(p.x - el.offsetWidth / 2);
        built.y = Math.round(p.y - el.offsetHeight / 2);
        el.style.left = `${built.x}px`;
        el.style.top = `${built.y}px`;
        scheduleEdges();
    }
    onGraphEdited(true);
    requestAnimationFrame(() => ensureNodeVisible(built));
    toast(`“${sourceTitle(built)}” spliced into the wire`);
    return true;
}
// The node a Graph-list entry stands for, built but not placed. Adding and replacing share
// this, so a node type has one definition of what it starts as. A declaration that only
// means something inside a function is refused here, with the same message as before.
function createGraphNode(type) {
    if (type === "magic") {
        // Magic is an operation, but it is offered as a graph tool: it sweeps the library for
        // the input rather than being one step of it.
        return makeNode("op", {op: MAGIC_OP});
    }
    if (type === "input") return makeNode("input", {title: TEXT_NODE_TITLE, text: "Hello, World!"});
    if (type === "file") return makeNode("file", {title: FILE_NODE_TITLE});
    if (type === "join") return makeNode("join", {title: "Join"});
    if (type === "diff") return makeNode("diff", {title: "Diff"});
    if (type === "hex") return makeNode("hex", {title: "Hex Viewer"});
    if (type === "template") return makeNode("template", {title: "Fstring", text: "{input1}"});
    if (type === "math") return makeNode("math", {title: "Math", text: "{input1} + {input2}"});
    if (type === "switch") return makeNode("switch", {title: "Switch"});
    if (type === "chess") return makeNode("chess", {title: "Chess"});
    if (type === "badapple") return makeNode("badapple", {title: "Bad Apple"});
    if (type === "note") return makeNode("note", {title: "Note"});
    if (type === "gate") return makeNode("gate", {title: "Gate"});
    if (["compact", "expand", "pick", "fork", "pngchunks", "pdfscan", "imginfo",
        "spectrogram", "audiolevels"].includes(type)) {
        return makeNode(type, {title: sourceTitle({type})});
    }
    if (type === "fnin" || type === "fnout") {
        // Only meaningful inside a function: these declare the ports of a definition.
        if (!editingFunctionId) {
            toast("Function input and output nodes only belong inside a function.", "error");
            return null;
        }
        return makeNode(type, {title: type === "fnin" ? "Function input" : "Function output"});
    }
    return null;
}

function addGraphNode(type, x, y) {
    const added = createGraphNode(type);
    if (!added) return;
    const p = (x === undefined) ? spawnPoint(added) : {x, y};
    added.x = Math.round(p.x);
    added.y = Math.round(p.y);
    state.nodes.push(added);
    setSelection([added.id]);
    renderAllNodes();
    onGraphEdited();
    requestAnimationFrame(() => ensureNodeVisible(added));
    if (window.innerWidth <= 900) closeSidebar();
}
// A new card goes in the middle of the view when that space is free, then in rings around
// it. Existing cards are measured from the DOM, so a resized or long operation is avoided
// by its real footprint; the card being added is not on screen yet, so its size is
// estimated from its type and the number of argument rows it will draw. Without this, two
// palette clicks landed on top of each other and a function's first wiring drag would hit
// the new card instead of the Function input port beneath it.
const SPAWN_GAP = 24;
const GRAPH_NODE_SIZES = {
    input: [310, 230], file: [310, 190], note: [310, 160], join: [310, 230],
    diff: [360, 260], hex: [400, 320], template: [340, 240], math: [340, 240],
    switch: [360, 260], gate: [310, 170], compact: [340, 250], expand: [340, 250],
    fork: [310, 170], pick: [310, 160], fn: [310, 190], fnin: [340, 300],
    fnout: [340, 190], symbol: [380, 380], badapple: [330, 220], chess: [380, 430],
    magic: [360, 240], pngchunks: [340, 240], pdfscan: [340, 240], imginfo: [340, 240],
    spectrogram: [430, 380], audiolevels: [400, 260]
};
function estimatedNodeSize(node) {
    if (node?.type === "op") {
        const rows = (OPS[node.op]?.args || []).filter(arg => arg.type !== "label").length;
        return {w: 310, h: 150 + rows * 44};
    }
    const [w, h] = GRAPH_NODE_SIZES[node?.type] || [310, 220];
    return {w, h};
}
function nodeWorldSize(node) {
    const el = nodeEl(node.id);
    return {w: node.w || el?.offsetWidth || 310, h: node.h || el?.offsetHeight || 220};
}
let spawnIndex = 0;
function spawnPoint(node = null) {
    const size = estimatedNodeSize(node);
    const c = stageCenterWorld();
    const baseX = Math.round(c.x - size.w / 2);
    const baseY = Math.round(c.y - size.h / 2);
    const boxes = state.nodes.map(n => {
        const s = nodeWorldSize(n);
        return {x: n.x, y: n.y, w: s.w, h: s.h};
    });
    const free = (x, y) => !boxes.some(b =>
        x < b.x + b.w + SPAWN_GAP && x + size.w + SPAWN_GAP > b.x &&
        y < b.y + b.h + SPAWN_GAP && y + size.h + SPAWN_GAP > b.y);
    if (free(baseX, baseY)) return {x: baseX, y: baseY};
    const stepX = Math.round(size.w + SPAWN_GAP);
    const stepY = Math.round(size.h + SPAWN_GAP);
    for (let ring = 1; ring <= 8; ring++) {
        // Prefer the open space to the right, then below. Starting at the top-left corner
        // could tuck a card under the toolbar or the sidebar even though the canvas is empty.
        const cells = [[ring, 0], [0, ring], [-ring, 0], [0, -ring],
            [ring, ring], [ring, -ring], [-ring, ring], [-ring, -ring]];
        for (let d = 1; d < ring; d++) {
            cells.push([ring, d], [d, ring], [-ring, d], [-d, ring],
                [ring, -d], [d, -ring], [-ring, -d], [-d, -ring]);
        }
        for (const [dx, dy] of cells) {
            const x = baseX + dx * stepX;
            const y = baseY + dy * stepY;
            if (free(x, y)) return {x, y};
        }
    }
    // A canvas with no free middle is rare; cascade rather than refusing to add the node.
    const offset = (spawnIndex++ % 6) * 30;
    return {x: baseX + offset, y: baseY + offset};
}

/* ================================================================ toolbar / actions */
/* On a phone the node list and the symbol ciphers are both drawers, and the desktop shows
 * each list in its own column. So each gets an icon button in the toolbar itself: the symbol
 * ciphers at the leading edge, the node list at the trailing edge, with File / Auto-run / Run
 * centred between them. Both buttons are hidden on the desktop. */
function addMobileDockButton(name, html, where) {
    const bar = document.querySelector(".toolbar");
    if (!bar || bar.querySelector(`[data-dock="${name}"]`)) return;
    if (where === "start") bar.insertAdjacentHTML("afterbegin", html);
    else bar.insertAdjacentHTML("beforeend", html);
}
// A drawer that is open is a drawer whose button says so, so the dock shows which list is up.
function setDockPressed(name, on) {
    const btn = document.querySelector(`.mobile-dock-btn[data-dock="${name}"]`);
    if (btn) btn.setAttribute("aria-expanded", String(Boolean(on)));
}

function initToolbar() {
    $("#toolbar").innerHTML = `
        <div class="tb-menu">
            <button class="tb-btn tb-menu-toggle" data-action="file-menu" aria-haspopup="menu" aria-expanded="false" title="New, load, save, import and export graphs">${iconFill("folder")}<span>File</span><span class="tb-caret">${iconFill("chevron")}</span></button>
        </div>
        <span class="tb-sep"></span>
        <button class="tb-switch" data-action="auto" title="Toggle automatic runs"><span class="switch" id="autoSwitch"></span><span class="switch-label">Auto-run</span></button>
        <button class="btn-run" id="runBtn" data-action="run">${iconFill("play")} Run</button>
    `;
    // The node list is a drawer on a phone, so its button closes the bar on the right.
    addMobileDockButton("nodes", `<button type="button" class="tb-btn mobile-dock-btn" data-dock="nodes" aria-controls="sidebar" aria-expanded="false" title="Show node list" aria-label="Show node list">${iconFill("nodes")}</button>`);
    autoSwitch = $("#autoSwitch");
    runButton = $("#runBtn");
    autoSwitch?.classList.toggle("on", Boolean(state?.autoRun));
    $("#toolbar").addEventListener("click", ev => {
        const dockBtn = ev.target.closest("[data-dock]");
        if (dockBtn) {
            if (dockBtn.dataset.dock === "nodes") toggleSidebar();
            else if (dockBtn.dataset.dock === "symbols") toggleSymbolDrawer();
            return;
        }
        const btn = ev.target.closest("[data-action]");
        if (!btn) return;
        const action = btn.dataset.action;
        if (action === "file-menu") { toggleFileMenu(); return; }
        if (action === "auto") toggleAutoRun();
        if (action === "run") { clearTimeout(runTimer); runGraph(true); }
    });
    initFileMenu();
    initExampleGallery();
}

function newGraph() {
    if (state.nodes.length && !confirm("Start a new graph? This replaces what is on the canvas. Saved graphs in this browser are kept.")) return;
    if (editingFunctionId) closeFunctionEditor();
    setCurrentGraphName("");
    applyGraph(blankState(), {fit: true});
    resetHistory();
    setRunStatus("", "Ready");
    renderFileMenu();
    toast("New graph");
}
